 const {build}=require('esbuild'),{MessageChannel}=await import('node:worker_threads'),os=await import('node:os'),path=await import('node:path'),temp=fs.mkdtempSync(path.join(os.tmpdir(),'ar-piece-mode-react-')),keys=['window','document','navigator','HTMLElement','Element','Node','requestAnimationFrame','IS_REACT_ACT_ENVIRONMENT','MessageChannel'],previous=new Map(keys.map(key=>[key,Object.getOwnPropertyDescriptor(globalThis,key)])),channels=[];
